"""
title: GuardPrompt — DI ženklas paveikslėliams
author: guardprompt
version: 1.0
description: Ant kiekvieno sugeneruoto paveikslėlio uždeda oficialų ES „AI GENERATED"
    ženklą (DI akto 50 str. skaidrumo prievolė). Ženklas įdegamas į patį vaizdą, todėl
    išlieka ir persiuntus ar atsisiuntus. Juodas/baltas variantas parenkamas automatiškai
    pagal fono šviesumą. NEJUNGTI kaip „Global" — kabinti prie paveikslėlių modelio
    (Workspace → Models → Filters).
required_open_webui_version: 0.5.0
"""

import base64
import io
import logging
import re
from typing import Optional

from pydantic import BaseModel, Field

log = logging.getLogger("gp_ai_label")

# Official EU "AI GENERATED" marks (digital-strategy.ec.europa.eu), trimmed to the
# artwork and downscaled. Embedded rather than mounted: a Filter function lives in
# OpenWebUI's database and cannot read files from the host, so this keeps it
# self-contained and surviving container rebuilds.
_ICON_BLACK_B64 = ""   # black pill, white text -> for LIGHT images
_ICON_WHITE_B64 = ""   # white pill, black text -> for DARK images

# data:image/png;base64,.... inside markdown, HTML or bare text
_DATA_URI_RE = re.compile(
    r"data:image/(?P<fmt>png|jpe?g|webp);base64,(?P<b64>[A-Za-z0-9+/=\s]{100,})",
    re.IGNORECASE,
)

# Written into the output PNG so a second pass (regeneration, edit) does not stamp
# the same picture twice.
_STAMP_KEY = "gp_ai_label"


class Filter:
    class Valves(BaseModel):
        enabled: bool = Field(default=True)
        # Badge width as a share of the image width. The EU mark is a wide pill
        # ("AI GENERATED"), so it needs far more width than a round icon would to
        # stay readable.
        width_pct: float = Field(default=0.095)
        min_width_px: int = Field(default=96)
        max_width_pct: float = Field(default=0.45)
        margin_pct: float = Field(default=0.025)
        # 1.0 on purpose: the embedded marks are the EU "transparent" variants,
        # whose pill is already ~50% see-through while the lettering stays opaque.
        # Multiplying that again would fade the official mark below "clearly
        # perceivable". Lower this only if a deployment needs it.
        opacity: float = Field(default=1.0)
        # Luminance (0-255) under which the WHITE badge is used instead of the black.
        dark_threshold: int = Field(default=128)

    def __init__(self):
        self.valves = self.Valves()

    # ---------- helpers ----------
    def _icon(self, dark_background: bool):
        from PIL import Image
        raw = _ICON_WHITE_B64 if dark_background else _ICON_BLACK_B64
        return Image.open(io.BytesIO(base64.b64decode(raw))).convert("RGBA")

    def _is_dark(self, img, box) -> bool:
        """Mean luminance of the area the badge will cover."""
        from PIL import ImageStat
        region = img.convert("RGB").crop(box)
        r, g, b = ImageStat.Stat(region).mean
        return (0.299 * r + 0.587 * g + 0.114 * b) < self.valves.dark_threshold

    def _stamp(self, data: bytes):
        """Burn the EU mark in. Returns (bytes, mime) or None to leave as-is.

        The ORIGINAL format is kept. Re-encoding a 1408x768 photo to PNG turned
        919 KB into several MB and bloated the chat database, so a JPEG stays a
        JPEG. Note what is lost either way: images from the model arrive with a
        SIGNED C2PA manifest (Google), and that signature covers the pixels — any
        visible mark invalidates it. Art. 50 wants BOTH a visible disclosure and
        machine-readable provenance, so the proper end state is to re-sign with our
        own C2PA certificate; until then the visible mark is the layer we can
        honestly provide, and the broken manifest is dropped rather than carried
        forward as if it still validated.
        """
        from PIL import Image
        from PIL.PngImagePlugin import PngInfo

        img = Image.open(io.BytesIO(data))
        fmt = (img.format or "PNG").upper()
        if img.info.get(_STAMP_KEY) or (img.info.get("comment") or b"") == _STAMP_KEY.encode():
            return None                      # already marked
        img = img.convert("RGBA")
        W, H = img.size
        if W < 64 or H < 32:
            return None                      # too small to carry a legible mark

        v = self.valves
        target_w = int(min(max(W * v.width_pct, v.min_width_px), W * v.max_width_pct))
        icon = self._icon(False)
        target_w = min(target_w, W - 4)
        target_h = max(1, round(icon.height * target_w / icon.width))
        if target_h > H // 3:                # keep it a badge, never a banner
            target_h = H // 3
            target_w = max(1, round(icon.width * target_h / icon.height))

        margin = int(min(W, H) * v.margin_pct)
        x = max(0, W - target_w - margin)
        y = max(0, H - target_h - margin)

        # Pick the variant that contrasts with what is actually behind the badge.
        icon = self._icon(self._is_dark(img, (x, y, x + target_w, y + target_h)))
        icon = icon.resize((target_w, target_h), Image.LANCZOS)

        if v.opacity < 1.0:
            alpha = icon.getchannel("A").point(lambda a: int(a * v.opacity))
            icon.putalpha(alpha)

        img.alpha_composite(icon, (x, y))

        out = io.BytesIO()
        if fmt in ("JPEG", "JPG", "MPO"):
            # JPEG has no alpha; the marker rides in the COM segment.
            img.convert("RGB").save(out, format="JPEG", quality=92,
                                    subsampling=0, optimize=True,
                                    comment=_STAMP_KEY.encode())
            return out.getvalue(), "jpeg"
        meta = PngInfo()
        meta.add_text(_STAMP_KEY, "1")
        img.save(out, format="PNG", pnginfo=meta)
        return out.getvalue(), "png"

    def _process(self, text: str) -> str:
        def repl(m):
            raw = re.sub(r"\s+", "", m.group("b64"))
            try:
                res = self._stamp(base64.b64decode(raw))
            except Exception as e:
                # Never break the answer over a decoration failure — but do log it,
                # because a silent miss is a compliance gap, not a cosmetic one.
                log.warning("[gp-ai-label] stamping failed: %s", e)
                return m.group(0)
            if res is None:
                return m.group(0)
            blob, mime = res
            return f"data:image/{mime};base64," + base64.b64encode(blob).decode()

        return _DATA_URI_RE.sub(repl, text)

    def _walk(self, node):
        """Stamp every image data-URI anywhere inside the message.

        A generated image does NOT arrive as markdown in `content`: OpenWebUI puts
        it in the message's `files` list as {"url": "data:image/jpeg;base64,..."}.
        Scanning only `content` therefore found nothing and the filter looked like
        it was doing nothing at all. Walking the whole structure covers `content`,
        multimodal part lists, `files[].url` and `images[]` alike, so a future
        change in where OpenWebUI parks the image cannot silently disable the mark.
        """
        if isinstance(node, bytes):
            # The stream hook hands us the raw SSE payload as BYTES, not a dict —
            # that is how the generated image actually arrives.
            try:
                s = node.decode("utf-8")
            except UnicodeDecodeError:
                return node
            if "data:image/" not in s:
                return node
            new = self._process(s)
            return new.encode("utf-8") if new != s else node
        if isinstance(node, str):
            return self._process(node) if "data:image/" in node else node
        if isinstance(node, list):
            return [self._walk(v) for v in node]
        if isinstance(node, dict):
            return {k: self._walk(v) for k, v in node.items()}
        return node

    # ---------- OpenWebUI hooks ----------
    def stream(self, event: dict) -> dict:
        """Stamp the image while it is still in the model's streamed response.

        This is the ONLY hook that sees it. `outlet` is handed a whitelist of
        fields (id/role/content/info/timestamp/output) — the `files` list holding
        the generated picture is stripped before the filter runs, and only
        content/output changes are persisted afterwards. So an outlet filter can
        never mark an image, no matter how it is written.
        """
        if not self.valves.enabled:
            return event
        try:
            probe = event if isinstance(event, (str, bytes)) else str(event)
            needle = b"data:image/" if isinstance(probe, bytes) else "data:image/"
            if needle in probe:
                return self._walk(event)
        except Exception as e:
            log.exception("[gp-ai-label] stream error: %s", e)
        return event

    async def outlet(self, body: dict, __user__: Optional[dict] = None,
                     __metadata__: Optional[dict] = None) -> dict:
        if not self.valves.enabled:
            return body
        try:
            # Kept as a safety net only. OpenWebUI hands outlet a whitelist of
            # fields (id/role/content/info/timestamp/output) with `files` stripped,
            # so the generated image never reaches here — the `stream` hook above
            # is what actually marks it. Verified against the running server.
            msgs = body.get("messages", [])
            for i, msg in enumerate(msgs):
                if isinstance(msg, dict) and msg.get("role") == "assistant":
                    msgs[i] = self._walk(msg)
        except Exception as e:
            log.exception("[gp-ai-label] outlet error: %s", e)
        return body
